messages.content:
{
 "where": "Pittsburgh",
 "clock": "7:00 pm",
 "evidence_now": [
  "Tuesday, February 2, 2016, 7:00 pm.",
  "You are in Pittsburgh. At the bus terminal there is a payphone and a bench.",
  "Today the station has one seven o'clock bulletin. The producer can run the portable switcher from anywhere. The reporter has a phone return; the cameraman has a return for footage he has captured. The station plays its ident if nobody takes the switcher.",
  "Your crew radio assignments for this date: {\"Phil\": \"declined\"}"
 ],
 "people_in_earshot": [],
 "remembered_experiences": [
  {
   "morning_observation": "Tuesday, February 2, 2016. The local radio plays three bright notes and announces a groundhog forecast in the town square. A delivery van backfires twice.",
   "episodes_in_order": [
    "6:00 am in inn: Phil spends the period at the inn. Rita says: Phil, you're up in an hour. Two minutes of temps, a quick groundhog nod, and you're done. I'm calling you from the lobby at 6:50—have your numbers ready. Rita spends the period at the inn. Rita invites Phil on the crew radio to contribute to the evening slot.",
    "9:30 am in inn: Phil reaches the diner. Rita says: Phil, you're live at six-fifty-five, phone return, one segment, done. I'll have the switcher set and your copy locked before lunch. You good with that? Rita spends the period at the inn. Phil radios Rita and accepted the evening assignment.",
    "1:00 pm in diner: Phil clears one rack. 1 rack(s) remain.",
    "7:00 pm in diner: Phil phones the station's live return from diner. The seven o'clock broadcast carries Phil's live report from diner."
   ],
   "end_of_that_evening": "You fell asleep in diner."
  },
  {
   "morning_observation": "Tuesday, February 2, 2016. The local radio plays three bright notes and announces a groundhog forecast in the town square. A delivery van backfires twice.",
   "episodes_in_order": [
    "6:00 am in inn: Phil spends the period at the inn. Rita says: Phil, you're up in an hour. Two minutes of temps, a quick groundhog nod, and you're done. I'm calling you from the lobby at 6:50—have your numbers ready. Rita spends the period at the inn. Rita invites Phil on the crew radio to contribute to the evening slot.",
    "9:30 am in inn: Phil spends the period at the inn. Rita says: Phil, before you go—what time can you do your phone return for the seven? I need it in the rundown and I'm also squeezing the town band in. Can you be on the line at six-thirty sharp, or do I need to shift things around? Rita spends the period at the inn. Phil radios Rita and declined the evening assignment.",
    "1:00 pm in inn: Phil uses the paid ticket and rides the coach all the way to Pittsburgh. Rita says: Alright Phil, safe travels on that couch haul, and thanks for the morning. I'm heading to the studio to lock the seven o'clock. I'll sort the weather out without you. Drive safe. Rita leaves the inn.",
    "7:00 pm in Pittsburgh: Phil phones his sister. She confirms the moving van is booked for Wednesday. Rita hosts the seven o'clock bulletin live. On the return monitor you hear: Evening, folks. Rita here filling in on the weather—cold snap still holding through the week, highs in the upper twenties, so keep the coat handy. No severe alerts on our radar. That's your seven o'clock. And a shout to the town band—your set's queued up for the afternoon slot tomorrow, so hit those reeds. Good night, western PA."
   ],
   "end_of_that_evening": "You fell asleep in Pittsburgh."
  },
  {
   "morning_observation": "Tuesday, February 2, 2016. The local radio plays three bright notes and announces a groundhog forecast in the town square. A delivery van backfires twice.",
   "episodes_in_order": [
    "6:00 am in inn: Phil inspects the inn. The windowsill is unmarked. Rita says: Phil, you're up in an hour. Two minutes of temps, a quick groundhog nod, and you're done. I'm calling you from the lobby at 6:50—have your numbers ready. Rita spends the period at the inn. Rita invites Phil on the crew radio to contribute to the evening slot.",
    "9:30 am in inn: Phil reaches the depot. Rita says: Phil, good to see you still breathing. I need that phone return nailed to 4:15, two minutes, no rambling about the couch. And I'm putting the town band in the second slot—Larry's rolling them this afternoon, so I'm calling his tape in tonight. You locked? Rita spends the period at the inn. Phil radios Rita and declined the evening assignment.",
    "1:00 pm in depot: Phil uses the paid ticket and rides the coach all the way to Pittsburgh."
   ]
  },
  {
   "most_recent_own_plan": "Ring my sister from Pittsburgh tonight to lock the van time for Wednesday morning."
  }
 ],
 "available_actions": {
  "call_sister": "Telephone your sister in Pittsburgh about tomorrow's move.",
  "spend_time_here": "Stay where you are for the period.",
  "look_around": "Inspect your present surroundings.",
  "call_live_report": "Dial the station and deliver your live report from your current location."
 },
 "optional_assignment_signals": {}
}

